

USE pulsefitness; 
-- Using the pulsefitness Schema to start off with


-- Creating the #GymLocation Table as it is an Entity in my ERD
-- Also adding the attributes accordingly and setting the types
CREATE TABLE GymLocation (
    LocationID INT PRIMARY KEY,
    LocationName VARCHAR(100),
    Address VARCHAR(255),
    City VARCHAR(100),
    State VARCHAR(50),
    Postcode VARCHAR(10),
    PhoneNumber VARCHAR(20),
    OpeningHours TEXT
);

-- Checking if the Table is correctly made
select * from GymLocation;

-- Creating the #MembershipType Table as it is an Entity in my ERD
-- Also adding the attributes accordingly and setting the types
CREATE TABLE MembershipType (
    MembershipTypeID INT PRIMARY KEY,
    TypeName VARCHAR(50),
    PricePerMonth DECIMAL(10, 2),
    ClassLimitPerWeek INT,
    FacilityAccessLevel VARCHAR(50),
    FreePTSessions INT
);

-- Creating the #Member Table as it is an Entity in my ERD
-- Also adding the attributes accordingly and setting the types
CREATE TABLE Member (
    MemberID INT PRIMARY KEY,
    FullName VARCHAR(100),
    DateOfBirth DATE,
    Gender VARCHAR(10),
    Email VARCHAR(100) UNIQUE,
    Phone VARCHAR(20),
    JoinDate DATE,
    MembershipTypeID INT,
    LocationID INT,
    ActiveStatus BOOLEAN,
    PreferredClassType VARCHAR(50),
    FOREIGN KEY (MembershipTypeID) REFERENCES MembershipType(MembershipTypeID),
    FOREIGN KEY (LocationID) REFERENCES GymLocation(LocationID)
);

-- Altering and updating the Phone attribute to 30 as 20 characters might be a bit less.
ALTER TABLE Member MODIFY Phone VARCHAR(30);

-- Creating the #Trainer Table as it is an Entity in my ERD
-- Also adding the attributes accordingly and setting the types
CREATE TABLE Trainer (
    TrainerID INT PRIMARY KEY,
    FullName VARCHAR(100),
    Specialization VARCHAR(50),
    Certification VARCHAR(100),
    Phone VARCHAR(20),
    Email VARCHAR(100) UNIQUE,
    LocationID INT,
    FOREIGN KEY (LocationID) REFERENCES GymLocation(LocationID)
);

-- Creating the #FitnessClass Table as it is an Entity in my ERD
-- Also adding the attributes accordingly and setting the types
CREATE TABLE FitnessClass (
    ClassID INT PRIMARY KEY,
    ClassName VARCHAR(100),
    TrainerID INT,
    LocationID INT,
    Schedule DATETIME,
    DurationMinutes INT,
    MaxCapacity INT,
    FOREIGN KEY (TrainerID) REFERENCES Trainer(TrainerID),
    FOREIGN KEY (LocationID) REFERENCES GymLocation(LocationID)
);

-- Creating the #ClassEnrollment Table as it is an Entity in my ERD
-- Also adding the attributes accordingly and setting the types
CREATE TABLE ClassEnrollment (
    EnrollmentID INT PRIMARY KEY,
    MemberID INT,
    ClassID INT,
    DateAttended DATE,
    FOREIGN KEY (MemberID) REFERENCES Member(MemberID),
    FOREIGN KEY (ClassID) REFERENCES FitnessClass(ClassID)
);

-- Creating the #PersonalTrainingSession Table as it is an Entity in my ERD
-- Also adding the attributes accordingly and setting the types
CREATE TABLE PersonalTrainingSession (
    SessionID INT PRIMARY KEY,
    TrainerID INT,
    MemberID INT,
    LocationID INT,
    SessionDate DATETIME,
    DurationMinutes INT,
    Feedback TEXT,
    Rating INT,
    FOREIGN KEY (TrainerID) REFERENCES Trainer(TrainerID),
    FOREIGN KEY (MemberID) REFERENCES Member(MemberID),
    FOREIGN KEY (LocationID) REFERENCES GymLocation(LocationID)
);


-- Creating the #FacilityVisit Table as it is an Entity in my ERD
-- Also adding the attributes accordingly and setting the types
CREATE TABLE FacilityVisit (
    VisitID INT PRIMARY KEY,
    MemberID INT,
    LocationID INT,
    CheckInTime DATETIME,
    CheckOutTime DATETIME,
    FacilityUsed VARCHAR(100),
    FOREIGN KEY (MemberID) REFERENCES Member(MemberID),
    FOREIGN KEY (LocationID) REFERENCES GymLocation(LocationID)
);

-- Checking if the Table is correctly made
select * from FacilityVisit;


-- Creating the #Payment Table as it is an Entity in my ERD
-- Also adding the attributes accordingly and setting the types
CREATE TABLE Payment (
    PaymentID INT PRIMARY KEY,
    MemberID INT,
    Amount DECIMAL(10, 2),
    PaymentDate DATE,
    PaymentMethod VARCHAR(50),
    Status VARCHAR(50),
    FOREIGN KEY (MemberID) REFERENCES Member(MemberID)
);

