-- As we have now Created and Populated the whole Database, we are now going to run some analysis to find Valuable business insights from it so that we can further learn and implement it to increase our Business.

-- Analysis 1 -- 

-- Behavior based Member segmentation 
-- Business Insight: Segmenting members into groups by behavior patterns. Behavioral patterns are the fundemental insights to know which consumers are providing most value and which customers should be sent what types of offers. 

SELECT M.MemberID, M.FullName,
       COUNT(DISTINCT CE.EnrollmentID) AS ClassCount,
       COUNT(DISTINCT FV.VisitID) AS VisitCount,
       COUNT(DISTINCT PTS.SessionID) AS PTSessions,
       CASE
           WHEN COUNT(DISTINCT CE.EnrollmentID) >= 4 AND COUNT(DISTINCT FV.VisitID) >= 5 THEN 'Highly Engaged'
           WHEN COUNT(DISTINCT CE.EnrollmentID) BETWEEN 1 AND 3 THEN 'Moderately Active'
           ELSE 'Low Engagement'
       END AS Segment
FROM Member M
LEFT JOIN ClassEnrollment CE ON M.MemberID = CE.MemberID
LEFT JOIN FacilityVisit FV ON M.MemberID = FV.MemberID
LEFT JOIN PersonalTrainingSession PTS ON M.MemberID = PTS.MemberID
GROUP BY M.MemberID, M.FullName;


-- Analysis 2 -- 

-- Customer lifetime value
-- Business Insight: Estimating the Total Spending per Member so that we can find who we should be targeting more aggresively. 
SELECT M.MemberID, M.FullName, SUM(P.Amount) AS TotalSpend
FROM Member M
JOIN Payment P ON M.MemberID = P.MemberID
WHERE P.Status = 'Paid'
GROUP BY M.MemberID
ORDER BY TotalSpend DESC;

-- Analysis 3 -- 

-- Churn risk flagging
-- Business Insight: Members with no visit or class in last 30 days so that we can predict the possible churn customers to retain them by throwing new offers, discounts or rewards.

SELECT M.MemberID, M.FullName, MT.TypeName AS MembershipType
FROM Member M
JOIN MembershipType MT ON M.MembershipTypeID = MT.MembershipTypeID
LEFT JOIN FacilityVisit FV ON M.MemberID = FV.MemberID AND FV.CheckInTime >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
LEFT JOIN ClassEnrollment CE ON M.MemberID = CE.MemberID AND CE.DateAttended >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
WHERE FV.VisitID IS NULL AND CE.EnrollmentID IS NULL;

-- Analysis 4 -- 

-- Location efficieny Score
-- Business Insight: Which Locations are providing most value Per visit

-- Step 1: Aggregate revenue per location
WITH LocationRevenue AS (
    SELECT M.LocationID, SUM(P.Amount) AS TotalRevenue
    FROM Member M
    JOIN Payment P ON M.MemberID = P.MemberID
    WHERE P.Status = 'Paid'
    GROUP BY M.LocationID
),

-- Step 2: Aggregate visits per location
LocationVisits AS (
    SELECT LocationID, COUNT(*) AS TotalVisits
    FROM FacilityVisit
    GROUP BY LocationID
)

-- Final output:
SELECT 
    GL.LocationName,
    COALESCE(V.TotalVisits, 0) AS TotalVisits,
    COALESCE(R.TotalRevenue, 0) AS TotalRevenue,
    ROUND(COALESCE(R.TotalRevenue, 0) / NULLIF(COALESCE(V.TotalVisits, 0), 0), 2) AS RevenuePerVisit
FROM GymLocation GL
LEFT JOIN LocationVisits V ON GL.LocationID = V.LocationID
LEFT JOIN LocationRevenue R ON GL.LocationID = R.LocationID;

-- Analysis 5 -- 

-- Peak Hours and Utilization
-- Business Insight: Which Hour of the day stays most busy so that we can figure out which hours needs more staffs or trainers.

SELECT HOUR(CheckInTime) AS HourOfDay, COUNT(*) AS VisitCount
FROM FacilityVisit
GROUP BY HOUR(CheckInTime)
ORDER BY VisitCount DESC;

-- Analysis 6 -- 

-- Identifying the most Profitable Membership Type
-- Business Insight: Focused marketing on High-Value membership types
SELECT MT.TypeName,
       COUNT(M.MemberID) AS MemberCount,
       SUM(P.Amount) AS TotalRevenue,
       ROUND(SUM(P.Amount) / COUNT(M.MemberID), 2) AS AvgRevenuePerMember
FROM Member M
JOIN MembershipType MT ON M.MembershipTypeID = MT.MembershipTypeID
JOIN Payment P ON M.MemberID = P.MemberID
WHERE P.Status = 'Paid'
GROUP BY MT.TypeName
ORDER BY TotalRevenue DESC;

-- Analysis 7 -- 

-- Detecting underutilised Active members 
-- Business Insight: Target the users with re-engagement offers
SELECT M.FullName, MT.TypeName, COUNT(FV.VisitID) AS VisitCount
FROM Member M
JOIN MembershipType MT ON M.MembershipTypeID = MT.MembershipTypeID
LEFT JOIN FacilityVisit FV ON M.MemberID = FV.MemberID
WHERE M.ActiveStatus = TRUE
GROUP BY M.MemberID
HAVING VisitCount < 3
ORDER BY VisitCount;

-- Analysis 8 -- 

-- Evaluating trainer performance via PT ratings 
-- Business Insight: Reward top trainers and identifying the improvement areas
SELECT T.FullName, COUNT(PTS.SessionID) AS SessionCount,
       ROUND(AVG(PTS.Rating), 2) AS AvgRating
FROM PersonalTrainingSession PTS
JOIN Trainer T ON PTS.TrainerID = T.TrainerID
GROUP BY T.FullName
HAVING SessionCount >= 5
ORDER BY AvgRating DESC;

-- Analysis 9 -- 

-- Top Performing Classes by location
-- Business Insight: Expand high demand classes and replicate them in other location

SELECT GL.LocationName, FC.ClassName, COUNT(*) AS Enrollments
FROM ClassEnrollment CE
JOIN FitnessClass FC ON CE.ClassID = FC.ClassID
JOIN GymLocation GL ON FC.LocationID = GL.LocationID
GROUP BY GL.LocationName, FC.ClassName
ORDER BY Enrollments DESC
LIMIT 10;

-- Analysis 10 -- 

-- Missed Revenue Due to failed or Refunded payments
-- Business Insight: Investigate and reduce payment failures to boost cash flow and recognise probable losses

-- Step 1 (Finding the total amount of Missed Revenue 

SELECT Status, COUNT(*) AS Count, SUM(Amount) AS MissedRevenue
FROM Payment
WHERE Status IN ('Failed', 'Refunded')
GROUP BY Status;

-- Step 2 (Finding the members with the dates who had failed or refunded payments)

SELECT 
    M.MemberID,
    M.FullName,
    P.PaymentDate,
    P.Amount,
    P.Status
FROM Payment P
JOIN Member M ON P.MemberID = M.MemberID
WHERE P.Status IN ('Failed', 'Refunded')
ORDER BY P.PaymentDate DESC;